\begin{equation}\label{RMT-model} 
\begin{split}
 \mathcal{D} =\left(\begin{array}{cc} 0 & iW \\ iW^\dagger & 0 \end{array}\right), ~
 W= H_1+i\mu H_2,\\
 H_1,H_2\in{\rm Herm}(N)\ \text{and}\ \mu\in[0,1]~~~
\end{split}
\end{equation}

\begin{equation}\label{distribution}
P(\mathcal{D})= \frac{1}{2^N \pi^{N^2}}\exp\left[-\frac{1}{2}\text{tr}(H_1^2+H_2^2)\right].
\end{equation}

\begin{equation}\label{eq:0Zdef}
		Z_N^{(N_f)} = \int d\mathcal{D} P(\mathcal{D})\prod_{f=1}^{N_{\rm f}}\det(m_f \mathbb{1}_{2N} +\mathcal{D})\,.
\end{equation}

\begin{equation}\label{Lag-phys}
\begin{split}
	 \mathcal{L} = & \overline{\psi}\bigl(\mathcal{D}_{\rm 3d}
	 + \mu_{\rm I} \sigma_3\tau_3+{\rm diag}(m_{\rm u},m_{\rm d})+j\tau_1\bigl)\psi,
\end{split}
\end{equation}

\begin{equation}\label{eq:Zval}
		Z_N^{(k,N_{\rm f}+k)} = \int d\mathcal{D} P(\mathcal{D})\frac{\prod_{j=1}^{N_{\rm f}+k}\det(\kappa_{{\rm f}, j} \mathbb{1}_{2N}+\mathcal{D})}{\prod_{j=1}^{k}\det(\kappa_{{\rm b}, j} \mathbb{1}_{2N}+\mathcal{D})},
\end{equation}

In the first step we rewrite the ratio of determinants in~\eqref{eq:Zval} by a Gaussian integral over an $N\times(2k|2N_{\rm f}+2k)$ rectangular supermatrix $V$. Then the integral over $H_1$ and $H_2$ is Gaussian which can be carried out explicitly, yielding
\begin{equation}\label{susy:partiton}
\begin{split}
		Z_N^{(k,N_{\rm f}+k)} = \; &\frac{1}{\pi^{2 Nk}}\int dV 
		\exp\big[\! -L\; \text{Str}\,V^\dagger V\kappa \\
		&-\text{Str}  (V^\dagger V\tau_1)^2/2-\mu^2\text{Str} (V^\dagger V\tau_2)^2/2 \big].
\end{split}
\end{equation}

\begin{equation}\label{susy:partiton}
\begin{split}
		Z_N^{(k,N_{\rm f}+k)} = \; &\frac{1}{\pi^{2 Nk}}\int dV 
		\exp\big[\! -L\; \text{Str}\,V^\dagger V\kappa \\
		&-\text{Str}  (V^\dagger V\tau_1)^2/2-\mu^2\text{Str} (V^\dagger V\tau_2)^2/2 \big].
\end{split}
\end{equation}

\begin{equation}
LV^\dagger V\tau_1\rightarrow \sqrt{N} U'=\sqrt{N}\left(\begin{array}{cc} U'_{\rm bb} & \eta^\dagger \\ \eta & U'_{\rm ff} \end{array}\right),
\end{equation}

\begin{equation}\label{susy:partiton.b}
\begin{split}
		Z_N^{(k_{\rm b},k_{\rm f})} \propto&
		\int d\tilde{\mu}(U')\; \text{Sdet}^{N}U' \exp\big[\!-\text{Str}\,U'\widehat{\kappa}\tau_1
		\\
		& - N\, \text{Str}\,{U'}^2/2 + \widehat{\mu}^2\text{Str} (U'\tau_3)^2/2 \big].
\end{split}
\end{equation}

\begin{equation}\label{sad.eq}
 U'^2=\mathbb{1}_{2N_{\rm f}}.
\end{equation}

\begin{align}\label{k-flav-f}
Z^{(0,N_{\rm f})}=\!\!\!\!\! \int\limits_{\text{U}(2N_{\rm f})} \!\!\!\!\!\!
d\mu(U)\exp\left[\text{tr}\,U\tau_3U^\dagger \widehat{\kappa}\tau_1-\frac{\widehat{\mu}^2}{2}\text{tr}(U\tau_3U^\dagger\tau_3)^2\right]\!.
\end{align}

\begin{equation}\label{level-part}
\rho(\lambda)=\frac{1}{\pi}\lim_{\varepsilon\to0}{\rm Re}\left.\partial_{\widehat{\kappa}_{\rm f}}Z_N^{(1,1)}\right|_{\widehat{\kappa}_{\rm b}=\widehat{\kappa}_{\rm f}=L\varepsilon-i \lambda}.
\end{equation}

In the large-$N$ limit the saddle point equation~\eqref{sad.eq} still applies though with a different dimension in the unit matrix. For this reason we use the parametrization
\begin{equation}
\begin{split}
{U'}_{\rm bb}& = Le^{-\vartheta_1\tau_3/2}e^{-\vartheta_2\tau_2/2}\tau_1e^{z_1\mathbb{1}_2+z_2 \tau_1}e^{\vartheta_2\tau_2/2}e^{\vartheta_1\tau_3/2},\\
{U'}_{\rm ff}& = e^{-i\varphi_1\tau_3/2}e^{-i\varphi_2\tau_2/2}\tau_1e^{i(z_3\mathbb{1}_2+z_4 \tau_1)}e^{i\varphi_2\tau_2/2}e^{i\varphi_1\tau_3/2},
\end{split}
\end{equation}
for the two diagonal blocks of $U'$. The angles take the values $z_1,z_2,\vartheta_1,\vartheta_2\in\mathbb{R}$, $\varphi_1\in[-\pi,\pi]$, and $\varphi_2,z_3,z_4\in[-\pi/2,\pi/2]$. From the saddle point equation and the properties of ${U'}_{\rm bb}$ and ${U'}_{\rm ff}$ we have to expand the variables $z_j$ as follows: $(z_1,z_2)=(\delta z_1/\sqrt{N},\delta z_2/\sqrt{N})$ and $(z_3,z_4)=(\delta z_3/\sqrt{N},$ $\delta z_4/\sqrt{N}), ~(z_3,z_4)=(\pi/2+\delta z_3/\sqrt{N},\pi/2+\delta z_4/\sqrt{N})$. The latter expansion for $z_3,z_4$ yields an algebraically $1/N$-suppressed term. The expansion to leading order in $1/N$ and integration over $\eta$ and $\delta z_j$ is quite lengthy and we omit it here. It is done in detail in~\cite{Kanazawa:2018b}. Afterwards we integrate over $\varphi_1$ and $\vartheta_1$ which yields the modified Bessel functions of first order, $I_j$, and of second order, $K_j$, respectively.

\begin{equation}
\begin{split}
{U'}_{\rm bb}& = Le^{-\vartheta_1\tau_3/2}e^{-\vartheta_2\tau_2/2}\tau_1e^{z_1\mathbb{1}_2+z_2 \tau_1}e^{\vartheta_2\tau_2/2}e^{\vartheta_1\tau_3/2},\\
{U'}_{\rm ff}& = e^{-i\varphi_1\tau_3/2}e^{-i\varphi_2\tau_2/2}\tau_1e^{i(z_3\mathbb{1}_2+z_4 \tau_1)}e^{i\varphi_2\tau_2/2}e^{i\varphi_1\tau_3/2},
\end{split}
\end{equation}

One important identity for the Bessel functions is the following~\cite[Eq.~(9.6.1)]{Abramowitz},
\begin{equation}
\lim_{\varepsilon\to0}{\rm Im}(\varepsilon-i \lambda)^\nu K_\nu(2(\varepsilon-i \lambda)\cosh\vartheta_2)=\frac{\pi}{2}\lambda^\nu J_\nu(2\lambda\cosh\vartheta_2)
\end{equation}
which simplifies the result a lot.

\begin{align}
\rho(\lambda)=\;&\frac{2}{\pi}\int_{-1}^1 dx\int_{-\infty}^\infty dy\exp\left[-2\widehat{\mu}^2\left(x^2+y^2\right)\right]\biggl[\left(2\widehat{\mu}^4(y^2-x^2+1)(y^2-x^2)-\widehat{\mu}^2\frac{x^2+y^2}{2}-\frac{1}{2}\lambda^2(2+y^2-x^2)-\frac{1}{4}\right)\notag\\
&\times\sqrt{1-x^2} J_1(2|\lambda|\sqrt{1-x^2})J_0(2\lambda\sqrt{1+y^2})+\lambda^2(1-x^2)\sqrt{1+y^2}J_0(2\lambda\sqrt{1-x^2})J_1(2|\lambda|\sqrt{1+y^2})\notag\\
&+\left(2\widehat{\mu}^2(y^2-x^2+1)+\frac{1}{4}\right)|\lambda|(1-x^2)J_0(2\lambda\sqrt{1-x^2})J_0(2\lambda\sqrt{1+y^2})\notag\\
&+\left(2\widehat{\mu}^2(y^2-x^2+1)+\frac{1}{4}\right)|\lambda|\sqrt{1+y^2}\sqrt{1-x^2}J_1(2\lambda\sqrt{1-x^2})J_1(2\lambda\sqrt{1+y^2})\biggl]\,.
\label{level.density}
\end{align}
